#include "mesh.h"OSErr meshStats ( FSSpec &theMeshFSSpec, struct meshHeader *theMeshHeader );OSErr meshStats ( FSSpec &theMeshFSSpec, struct meshHeader *theMeshHeader ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	long readCount = 1088L;			OSErr		theError;//----------------------------------------------------------------------------------------			theError = FSpOpenDF ( &theMeshFSSpec, fsRdPerm, &theMeshFileRef );	if ( theError != noErr ){		return theError;	}	FSRead ( theMeshFileRef, &readCount, theMeshHeader);	FSClose ( theMeshFileRef );		if ( theMeshHeader->type != 'mesh' ){		return -1;	}	theMeshHeader->meshOffset = 1088;						//real start of stuff after headers	theMeshHeader->waterMaskOffset += theMeshHeader->meshOffset;	theMeshHeader->itemTypeOffset += theMeshHeader->meshOffset;	theMeshHeader->itemOffset += theMeshHeader->meshOffset;	theMeshHeader->actionOffset += theMeshHeader->meshOffset;		return noErr;}